const baseline = $('Evaluate request').first().json;
const content = (typeof $json.output === 'string' && $json.output.trim()) ? $json.output.trim() : null;
const failed = !content || Boolean($json.error);
return [{ json: {
  ...baseline,
  ai_advisory: { provider: 'OpenAI', status: failed ? 'unavailable' : 'completed', content: content, note: failed ? 'تعذر الحصول على تحليل النموذج؛ تم الاحتفاظ بنتيجة التحقق الحتمية.' : 'هذه توصية تفسيرية فقط ولا تغيّر نتيجة التحقق الحتمية.' },
  execution_authority: 'read_only_advisory',
  side_effects_performed: false,
} }];
